// This code has been fully generated by an AI.

package web

import (
	"net/http"
	"net/url"
	"strconv"
	"time"

	"github.com/stefanluchs/my-velo/internal/sport"
	"github.com/stefanluchs/my-velo/internal/store"
)

const listPageSize = 50

// listQuery is the parsed, validated filter of the activity list. Invalid
// values are ignored instead of rejected, so a stale bookmark still works.
type listQuery struct {
	Category string // sport.Category ID or ""
	Year     int    // 0 = all years
	From, To string // YYYY-MM-DD, local dates, To inclusive
	Page     int
}

func parseListQuery(q url.Values) listQuery {
	lq := listQuery{Page: 1}
	if _, ok := sport.ByID(q.Get("cat")); ok {
		lq.Category = q.Get("cat")
	}
	if y, err := strconv.Atoi(q.Get("year")); err == nil && y >= 1990 && y <= 2100 {
		lq.Year = y
	}
	if _, err := time.Parse(time.DateOnly, q.Get("from")); err == nil {
		lq.From = q.Get("from")
	}
	if _, err := time.Parse(time.DateOnly, q.Get("to")); err == nil {
		lq.To = q.Get("to")
	}
	if p, err := strconv.Atoi(q.Get("page")); err == nil && p > 1 && p < 100000 {
		lq.Page = p
	}
	return lq
}

// Filter converts the query into a store filter. An explicit date range
// takes precedence over the year.
func (lq listQuery) Filter() store.ListFilter {
	var f store.ListFilter
	if c, ok := sport.ByID(lq.Category); ok {
		if c.ID == sport.Other {
			f.ExcludeSports = sport.KnownSports()
		} else {
			f.Sports = c.Sports
		}
	}
	if lq.From != "" || lq.To != "" {
		if t, err := time.Parse(time.DateOnly, lq.From); err == nil {
			f.From = t
		}
		if t, err := time.Parse(time.DateOnly, lq.To); err == nil {
			f.To = t.AddDate(0, 0, 1)
		}
	} else if lq.Year != 0 {
		f.From = time.Date(lq.Year, 1, 1, 0, 0, 0, 0, time.UTC)
		f.To = f.From.AddDate(1, 0, 0)
	}
	return f
}

// URL returns the list URL for this query with another page.
func (lq listQuery) URL(page int) string {
	v := url.Values{}
	if lq.Category != "" {
		v.Set("cat", lq.Category)
	}
	if lq.Year != 0 {
		v.Set("year", strconv.Itoa(lq.Year))
	}
	if lq.From != "" {
		v.Set("from", lq.From)
	}
	if lq.To != "" {
		v.Set("to", lq.To)
	}
	if page > 1 {
		v.Set("page", strconv.Itoa(page))
	}
	if len(v) == 0 {
		return "activities"
	}
	return "activities?" + v.Encode()
}

type listData struct {
	Query      listQuery
	Categories []sport.Category
	Years      []int
	Activities []store.Activity
	Totals     store.Totals
	Pages      int
	PrevURL    string
	NextURL    string
}

func (s *server) activities(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	lq := parseListQuery(r.URL.Query())
	f := lq.Filter()

	totals, err := s.Store.Totals(ctx, f)
	if err != nil {
		s.serverError(w, "sum activities", err)
		return
	}
	years, err := s.Store.Years(ctx)
	if err != nil {
		s.serverError(w, "list years", err)
		return
	}
	f.Limit, f.Offset = listPageSize, (lq.Page-1)*listPageSize
	list, err := s.Store.List(ctx, f)
	if err != nil {
		s.serverError(w, "list activities", err)
		return
	}

	d := listData{Query: lq, Categories: sport.Categories, Years: years, Activities: list, Totals: totals,
		Pages: max(1, (totals.Count+listPageSize-1)/listPageSize)}
	if lq.Page > 1 {
		d.PrevURL = lq.URL(lq.Page - 1)
	}
	if lq.Page < d.Pages {
		d.NextURL = lq.URL(lq.Page + 1)
	}
	s.render(w, r, "activities.html", "activities", d)
}
